head.script:
/* ★Wcraft guide★    
스크립트 수작업 유의사항
*/


//★Wcraft guide★ include부분 주석처리 -> include("../js/PopupCalendar.js");
//★Wcraft guide★ include부분 주석처리 -> include("../js/utils.js");
//★Wcraft guide★ include부분 주석처리 -> include("../js/session.js");
//★Wcraft guide★ include부분 주석처리 -> include("../js/stf.js");
//★Wcraft guide★ include부분 주석처리 -> include("../js/libRoundPanel.js");
//★Wcraft guide★ include부분 주석처리 -> include("../js/common.js");
scwin.vScrenID = "ULDSTF21205.xml";
scwin.onpageload = function() {
    scwin.gform_onload();
};
scwin.onpageunload = function() {
};
scwin.fn_SetCode = function() {
    gDepCd = js_dep_cd;
    gEmpNo = js_emp_no;

    // 팀 리스트 박스(소속부서와 같은 상위부서인 팀)	
    //dts_dep.DataID = "/CodeAction.do?method=listDepCdCode&For=R";
    dts_dep.DataID = "/CodeAction.do?method=getDepUpCode" + "&inputMessageId=CODE_EMPDEP_IN&outputMessageId=CODE_EMPDEP_OUT" + "&For=R&DEP_CD=" + gDepCd;
    dts_dep.Reset();

    //담당자 리스트 박스(소속부서와 같은 상위부서인 팀원)	
    dts_emp.DataID = "/CodeAction.do?method=getEmpNoDepCode" + "&inputMessageId=CODE_EMPDEP_IN&outputMessageId=CODE_EMPDEP_OUT" + "&For=R&DEP_CD=" + gDepCd;
    dts_emp.Reset();
};
scwin.fn_list_sync_1 = function() {
    var url = "/listingCommon.do";
    url += "?SCREN_ID=" + scwin.vScrenID + "&SCREN_PROCES_TP_CD=" + SCREN_PROCS_TP_CD_01;
    url += "&method=listGeneral" + "&outputMessageId=LISTED_SEARCH_ICR_OUT" + "&service=krx.lds.stf.listingcommon.services.ListingCommonApp" + "&queryId=lds.stf.lstsrch.listedsearch.tabfirco.icr.select.condition" + "&{P}param01=" + $c.stf.getObjectValue(txb_ISUR_CD) + // 법인코드
        "&{P}param02=" + $c.stf.getObjectValue(txb_ISUR_CD) + "&{P}param03=" + $c.stf.getObjectValue(cmb_TeamList) + "&{P}param04=" + $c.stf.getObjectValue(cmb_TeamList) + "&{P}param05=" + $c.stf.getObjectValue(cmb_EmpList) + "&{P}param06=" + $c.stf.getObjectValue(cmb_EmpList);
    dts_admCoList.DataID = encodeURI(url);
    dts_admCoList.reset();
    $c.cm.ShowWin(grd_adm_co1);
};
scwin.fn_list_sync_2 = function() {
    if ($c.stf.compareFromToDate2(edt_SDate, edt_EDate)) {
        var url = "/listingCommon.do";
        url += "?SCREN_ID=" + scwin.vScrenID + "&SCREN_PROCES_TP_CD=" + SCREN_PROCS_TP_CD_01;
        url += "&method=listGeneral" + "&outputMessageId=LISTED_SEARCH_ICR_OUT" + "&service=krx.lds.stf.listingcommon.services.ListingCommonApp" + "&queryId=lds.stf.lstsrch.listedsearch.tabsecco.icr.select.condition" + "&{P}param01=" + $c.stf.getObjectValue(txb_ISUR_CD) + // 법인코드
            "&{P}param02=" + $c.stf.getObjectValue(txb_ISUR_CD) + // 법인코드
            "&{P}param03=" + $c.stf.getObjectValue(cmb_TeamList) + "&{P}param04=" + $c.stf.getObjectValue(cmb_TeamList) + "&{P}param05=" + $c.stf.getObjectValue(cmb_EmpList) + "&{P}param06=" + $c.stf.getObjectValue(cmb_EmpList) + "&{P}param07=" + $c.stf.getObjectValue(edt_SDate) + // 시작일자
            "&{P}param08=" + $c.stf.getObjectValue(edt_EDate); // 종료일자

        dts_admCoList.DataID = encodeURI(url);
        dts_admCoList.reset();
        $c.cm.ShowWin(grd_adm_co2);
    }
};
scwin.showPanCnd = function(idx) {
    pan_cnd.style.display = (idx == 1 ? "none" : "");
};
scwin.dts_admCoList_OnLoadError = function() {
    $c.stf.alert_error(dts_admCoList);
};
scwin.dts_admCoList_OnLoadCompleted = function(rowcount) {
    if (rowcount <= 0) {
        dts_admCoList.removeAll();
    }
    if (adm_tab_co.getSelectedTabIndex() == 1) {
        var rcnt = dts_admCoList.getCellData(rowcount, "NO");
        $c.stf.FillGridHeaderTotalCnt(rcnt, panel_page);
        $c.cm.CloseWin(rowcount, grd_adm_co1); //데이터 로딩중닫기 및 조회없음 처리

    } else {
        $c.stf.FillGridHeaderTotalCnt(rowcount, panel_page);
        $c.cm.CloseWin(rowcount, grd_adm_co2); //데이터 로딩중닫기 및 조회없음 처리

    }
};
scwin.adm_tab_co_PreSelChangeNotify = function(nIndex) {
    if (nIndex == 1) {
        scwin.fn_list_sync_1();
    } else if (nIndex == 2) {
        scwin.fn_list_sync_2();
    }
};
scwin.btn_toexcel_onclick = function() {
    $c.stf.doLogSave(scwin.vScrenID, SCREN_PROCS_TP_CD_07); // 엑셀
    if (adm_tab_co.getSelectedTabIndex() == 1) {
        $c.data.downloadGridViewExcel(grd_adm_co1, "현재투자주의환기종목현황", "", "8");
    } else {
        $c.data.downloadGridViewExcel(grd_adm_co2, "투자주의환기종목지정내역", "", "8");
    }
};
scwin.btn_select_onclick = function() {
    if (adm_tab_co.getSelectedTabIndex() == 1) {
        scwin.fn_list_sync_1();
    } else {
        scwin.fn_list_sync_2();
    }
};
scwin.btn_close_onclick = function() {
    self.close();
};
scwin.btn_SDate_onclick = function() {
    popUpCalendar2(edt_SDate);
};
scwin.btn_EDate_onclick = function() {
    popUpCalendar2(edt_EDate);
};
scwin.adm_tab_co_OnSelChanged = function(nIndex) {
    scwin.showPanCnd(nIndex);
};
scwin.MxDataSet_com_isur_OnFilter = function(row) {
    if (skw != "" && foColum == "1") {
        f1 = MxDataSet_com_isur.getCellData(row, "COM_ABBRV");
        f2 = MxDataSet_com_isur.getCellData(row, "OLD_COM_ABBRV");
        if (f1.indexOf(skw) != -1 || f2.indexOf(skw) != -1) return true;

        else return false;
    } else return true;
};
scwin.txb_ISUR_CD_onkeyup = function() {
    if (txb_ISUR_CD.getValue() == "") {
        Grd_com_isur.style.display = "none";
    } else {
        if (window.event.keyCode == 40) {
            //아래화살표눌렀을때 그리드로 포커스
            Grd_com_isur.focus();
        } else {
            $c.cm.fn_com_isur_nm(window.event.keyCode);
        }
    }
};
scwin.txb_ISUR_CD_onfocus = function() {
    Grd_com_isur.style.display = "none";
};
scwin.txb_ISUR_CD_onblur = function() {
    if (stFocusGrid == false) {
        Grd_com_isur.style.display = "none";
    }
    if (txb_ISUR_CD.getValue() == "") {
        txb_COM_NM.setValue("");
    }
};
scwin.img_COM_NM_onclick = function() {
    $c.cm.IsurcdSearch(txb_ISUR_CD, txb_COM_NM);
};
scwin.Grd_com_isur_OnKeyPress = function(kcode) {
    if (kcode == '13') {
        $c.cm.fn_com_Confirm_set();
    }
};
scwin.Grd_com_isur_OnDblClick = function(row, colid) {
    $c.cm.fn_com_Confirm_set();
};
scwin.Grd_com_isur_OnClick = function(row, colid) {
    Grd_com_isur.style.display = "";
};
scwin.Grd_com_isur_OnSetFocus = function() {
    stFocusGrid = true;
};
scwin.Grd_com_isur_OnKillFocus = function() {
    stFocusGrid = false;
    Grd_com_isur.style.display = "none";
};
scwin.cmb_PeriodTp_OnSelChange = function() {
    var vTp = $c.cp.valueOfIndex(cmb_PeriodTp, "VALUE", cmb_PeriodTp.getSelectedIndex());
    $c.stf.fn_setFromToDate(vTp, edt_SDate, edt_EDate);
};
scwin.cmb_TeamList_OnSelChange = function() {
    gDepCd = $c.cp.valueOfIndex(cmb_TeamList, "VALUE", cmb_TeamList.getSelectedIndex());
    if (gDepCd == '') {
        $c.stf.setObjectValue(cmb_EmpList, '');
    }
    dts_emp.UseFilter = true;
    dts_emp.Filter();
    dts_emp.sort("DEP_CD", 0);
    //dts_emp.sort(); // W-Craft 주석처리 

};
scwin.dts_emp_OnFilter = function(row) {
    //  부서코드에  해당하는 사원을 가져온다.
    if (gDepCd == "") {
        // 전체일 경우 모두 보여준다.
        return true;
    } else {
        if (dts_emp.getCellData(row, "dep_cd") == gDepCd ||
            dts_emp.getCellData(row, "dep_cd") == "") {
            return true;
        } else {
            return false;
        }
    }
};
scwin.dts_emp_OnLoadError = function() {
    $c.stf.alert_error(dts_emp);
};
scwin.dts_dep_OnLoadError = function() {
    $c.stf.alert_error(dts_dep);
};
scwin.gform_onload = function() {
    $c.cm.PanelToGroupBox(panel_Top);
    $c.stf.Combo_CBDataSetPeriod(cmb_PeriodTp);
    var vCurDate = $c.ut.cGetToday("yyyymmdd");
    edt_SDate.setValue($c.ut.cGetMinusDate2(vCurDate, 365)); // 일년 날짜
    edt_EDate.setValue($c.ut.cGetToday("yyyymmdd"));
    adm_tab_co.setSelectedTabIndex(1);
    scwin.showPanCnd(adm_tab_co.getSelectedTabIndex());
    scwin.fn_SetCode();
    scwin.fn_list_sync_1();
    $c.cm.fn_com_isur(txb_ISUR_CD, txb_COM_NM);
};
